begin;
do $$
declare owner_a uuid:=gen_random_uuid();owner_b uuid:=gen_random_uuid();customer_a uuid:=gen_random_uuid();customer_b uuid:=gen_random_uuid();slug_a text:='contact-qa-'||substr(owner_a::text,1,8);slug_b text:='contact-qa-'||substr(owner_b::text,1,8);contacts jsonb;campaign uuid;recipient uuid;draft jsonb;
begin
 insert into auth.users(id,aud,role,email,created_at,updated_at) select u,'authenticated','authenticated','contacts-qa-'||u||'@example.invalid',now(),now() from unnest(array[owner_a,owner_b]) u;
 insert into auth.users(id,aud,role,email,created_at,updated_at,raw_user_meta_data) select u,'authenticated','authenticated','contacts-qa-'||u||'@example.invalid',now(),now(),jsonb_build_object('full_name',case when u=customer_a then 'Customer Alpha' else 'Customer Beta' end,'date_of_birth','1995-04-20','whatsapp_number','+919876543210') from unnest(array[customer_a,customer_b])u;
 insert into public.studioflow_accounts(user_id,draft) values(owner_a,'{}'),(owner_b,'{}');
 insert into public.studioflow_websites(owner_id,slug,content) values(owner_a,slug_a,'{"profile":{"businessName":"Salon A"}}'),(owner_b,slug_b,'{"profile":{"businessName":"Salon B"}}');
 insert into public.studioflow_bookings(owner_id,customer_id,stylist_id,starts_at,ends_at,status,payload) values(owner_a,customer_a,'qa',now()-interval '1 day',now()-interval '23 hours','confirmed','{"clientName":"Alpha","clientPhone":"9876543210","servicePrice":1000,"amountPaid":250}'),(owner_b,customer_b,'qa',now()-interval '1 day',now()-interval '23 hours','confirmed','{"clientName":"Beta","clientPhone":"9876543210","servicePrice":1000,"amountPaid":250}');
 perform set_config('request.jwt.claim.sub',owner_a::text,true);execute 'set local role authenticated';
 contacts:=public.studioflow_owner_contacts();
 if jsonb_array_length(contacts)<>1 or contacts->0->>'name'<>'Customer Alpha' then raise exception 'FAIL owner contact scope';end if;
 if contacts->0->>'dateOfBirth' is not null or contacts->0->>'optIn'<>'false' then raise exception 'FAIL default privacy';end if;
 begin perform public.studioflow_owner_prepare_campaign('Offer','Hello {name}',array[customer_a]);raise exception 'FAIL no-consent campaign accepted';exception when raise_exception then if sqlerrm='FAIL no-consent campaign accepted' then raise;end if;end;
 begin perform public.studioflow_owner_save_contact(customer_b,'VIP','notes',false);raise exception 'FAIL cross-salon write';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',customer_a::text,true);
 perform public.studioflow_customer_save_marketing_preference(slug_a,true,true);
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 contacts:=public.studioflow_owner_contacts();
 if contacts->0->>'dateOfBirth'<>'1995-04-20' or contacts->0->>'optIn'<>'true' then raise exception 'FAIL permission projection';end if;
 perform public.studioflow_owner_save_contact(customer_a,'VIP,regular','Customer requested updates',false);
 campaign:=public.studioflow_owner_prepare_campaign('Festival','Hello {name}, visit {salon}: {booking_link}',array[customer_a,customer_a]);
 contacts:=public.studioflow_owner_campaigns();
 if jsonb_array_length(contacts->0->'recipients')<>1 then raise exception 'FAIL duplicate recipients';end if;
 recipient:=(contacts->0->'recipients'->0->>'id')::uuid;
 draft:=public.studioflow_owner_open_campaign_draft(recipient);
 if draft->>'phone'<>'919876543210' or position('Customer Alpha' in draft->>'text')=0 or position('Salon A' in draft->>'text')=0 or position(slug_a in draft->>'text')=0 or position('Reply STOP' in draft->>'text')=0 then raise exception 'FAIL trusted draft';end if;
 perform set_config('request.jwt.claim.sub',owner_b::text,true);
 if jsonb_array_length(public.studioflow_owner_campaigns())<>0 then raise exception 'FAIL campaign privacy';end if;
 begin perform public.studioflow_owner_open_campaign_draft(recipient);raise exception 'FAIL cross-salon draft';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',customer_a::text,true);perform public.studioflow_customer_save_marketing_preference(slug_a,false,false);
 perform set_config('request.jwt.claim.sub',owner_a::text,true);
 if public.studioflow_owner_contacts()->0->>'dateOfBirth' is not null then raise exception 'FAIL DOB opt-out';end if;
 begin perform public.studioflow_owner_open_campaign_draft(recipient);raise exception 'FAIL opted-out draft';exception when raise_exception then if sqlerrm='FAIL opted-out draft' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',customer_a::text,true);perform public.studioflow_customer_save_marketing_preference(slug_a,true,true);
 perform set_config('request.jwt.claim.sub',owner_a::text,true);perform public.studioflow_owner_save_contact(customer_a,'VIP','STOP request',true);
 begin perform public.studioflow_owner_open_campaign_draft(recipient);raise exception 'FAIL DNC draft';exception when raise_exception then if sqlerrm='FAIL DNC draft' then raise;end if;end;
 begin execute 'select * from public.studioflow_customer_marketing_preferences';raise exception 'FAIL direct permission read';exception when insufficient_privilege then null;end;
 execute 'reset role';
 raise notice 'PASS salon isolation, default DOB privacy, customer opt-in, birthday sharing, contact notes, audience validation, deduplication, trusted manual draft, campaign privacy, opt-out and STOP suppression';
end $$;
rollback;
